<?php
namespace App\Console\Commands;use App\Services\DevOps\{ReleaseService,DeploymentDriftService};use Illuminate\Console\Command;use Illuminate\Support\Facades\Storage;
final class DevOpsDriftCommand extends Command {protected $signature='zigo:devops-drift {--environment=all} {--verify-files} {--json}';protected $description='Detecta drift sin modificar archivos.';public function handle(ReleaseService $releases,DeploymentDriftService $drift):int{$e=(string)$this->option('environment');if(!in_array($e,['stage','production','all'],true))return self::INVALID;$out=[];foreach($e==='all'?['stage','production']:[$e] as $env){$release=$releases->active($env);$out[$env]=$release?$drift->inspect($release,(bool)$this->option('verify-files')):['environment'=>$env,'status'=>'unknown','message'=>'Sin release activa.'];}$path='private/devops-drift-reports/drift-'.now()->format('Ymd-His').'.json';Storage::disk('local')->put($path,json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$this->line($this->option('json')?json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES):'Reporte: storage/app/'.$path);return self::SUCCESS;}}
